package com.example.social.controller;
import com.example.social.model.SocialPost;import com.example.social.repository.PostRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController{private final PostRepository posts;public AnalyticsController(PostRepository p){posts=p;}@GetMapping("/summary") public Map<String,Long> summary(Authentication a){return Map.of("total",posts.countByOwnerEmail(a.getName()),"drafts",posts.countByOwnerEmailAndStatus(a.getName(),SocialPost.Status.DRAFT),"scheduled",posts.countByOwnerEmailAndStatus(a.getName(),SocialPost.Status.SCHEDULED),"publishRequested",posts.countByOwnerEmailAndStatus(a.getName(),SocialPost.Status.PUBLISH_REQUESTED));}}
